import pathlib
r=pathlib.Path('.')
def put(p,s): (r/p).write_text(s,encoding='utf-8')
put('components/Header.tsx',''''use client';
import {ArrowUpRight,Menu,X,Phone} from 'lucide-react';import Link from 'next/link';import {useEffect,useRef,useState} from 'react';import {createPortal} from 'react-dom';import {usePathname} from 'next/navigation';import {clinic} from '@/lib/config';
const links=[['Treatments','/treatments'],['Our Clinic','/about'],['Specialists','/specialists'],['Journal','/journal'],['Client voices','/reviews'],['Contact','/contact']];
export default function Header(){const path=usePathname();const [menuPath,setMenuPath]=useState<string|null>(null);const open=menuPath===path;const [scrolled,setScrolled]=useState(false);const trigger=useRef<HTMLButtonElement>(null);const drawer=useRef<HTMLDivElement>(null);const closeButton=useRef<HTMLButtonElement>(null);
useEffect(()=>{let last=window.scrollY>40;setScrolled(last);const fn=()=>{const next=window.scrollY>40;if(next!==last){last=next;setScrolled(next)}};window.addEventListener('scroll',fn,{passive:true});return()=>window.removeEventListener('scroll',fn)},[]);
useEffect(()=>{if(!open)return;document.documentElement.dataset.menuOpen='true';closeButton.current?.focus({preventScroll:true});const desktop=matchMedia('(min-width:1101px)');const close=()=>setMenuPath(null);const resize=()=>{if(desktop.matches)close()};const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const items=Array.from(drawer.current?.querySelectorAll<HTMLElement>('a,button')||[]);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};desktop.addEventListener('change',resize);window.addEventListener('keydown',key);window.addEventListener('pageshow',close);return()=>{delete document.documentElement.dataset.menuOpen;desktop.removeEventListener('change',resize);window.removeEventListener('keydown',key);window.removeEventListener('pageshow',close);if(!desktop.matches)trigger.current?.focus({preventScroll:true})}},[open]);
return <><header className={scrolled?'header solid':'header'} inert={open}><Link href="/" className="brand">REVIVE<span>AESTHETICS CLINIC</span></Link><nav className="nav" aria-label="Main navigation">{links.map(([n,u])=><Link key={u} href={u}>{n}</Link>)}<Link className="nav-book" href="/online-consultation">Book online<ArrowUpRight size={18} aria-hidden="true"/></Link></nav><button ref={trigger} className="menu-toggle" aria-controls="mobile-navigation" aria-label="Open navigation" aria-expanded={open} onClick={()=>setMenuPath(path)}><span>Menu</span><Menu size={20} aria-hidden="true"/></button></header>{open&&createPortal(<div ref={drawer} className="mobile-drawer" role="dialog" aria-modal="true" aria-label="Navigation"><div className="drawer-header"><Link className="brand" href="/" onClick={()=>setMenuPath(null)}>REVIVE<span>AESTHETICS CLINIC</span></Link><button ref={closeButton} aria-label="Close navigation" className="drawer-close" onClick={()=>setMenuPath(null)}><X size={23} aria-hidden="true"/></button></div><div className="drawer-content"><span className="drawer-eyebrow">A MORE PERSONAL KIND OF CARE</span><nav id="mobile-navigation" aria-label="Mobile navigation">{links.map(([n,u],i)=><Link key={u} href={u} style={{'--item':i} as React.CSSProperties} onClick={()=>setMenuPath(null)}><small>0{i+1}</small><span>{n}</span><ArrowUpRight size={21} aria-hidden="true"/></Link>)}</nav><Link className="drawer-book" href="/online-consultation" onClick={()=>setMenuPath(null)}>Book an online consultation<ArrowUpRight size={20} aria-hidden="true"/></Link><div className="drawer-contact"><span>MIRPUR, AJK</span><a href={clinic.telephone}><Phone size={14} aria-hidden="true"/>{clinic.phone}</a></div></div></div>,document.body)}</>}
''')
put('components/Motion.tsx',''' 'use client';
import gsap from 'gsap';import {ScrollTrigger} from 'gsap/ScrollTrigger';import {useGSAP} from '@gsap/react';
gsap.registerPlugin(ScrollTrigger,useGSAP);
// Mobile toolbar resizes must not repeatedly refresh scroll positions.
ScrollTrigger.config({ignoreMobileResize:true});
export default function Motion(){useGSAP(()=>{const mm=gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)',()=>{
 const intro=gsap.timeline({defaults:{ease:'power3.out'}});intro.from('.cinema-image',{opacity:.65,duration:1},0).from('.hero-line',{y:28,opacity:.15,stagger:.12,duration:.9},.05);
 const targets=gsap.utils.toArray<HTMLElement>('.reveal-line,.approach-visual,.principle,.collection-heading h2,.collection-tabs,.clinic-heading h2,.clinic-placeholder,.consultation-title h2,.footer-invitation h2');
 const tweens:gsap.core.Tween[]=[];const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);tweens.push(gsap.fromTo(entry.target,{y:30,opacity:.25},{y:0,opacity:1,duration:.85,ease:'power3.out',clearProps:'transform,opacity'}))}},{threshold:.12,rootMargin:'0px 0px -35px 0px'});targets.forEach(el=>observer.observe(el));
 const scene=document.querySelector('.perspective-scene');const sceneObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){sceneObserver.disconnect();tweens.push(gsap.fromTo('.scene-word',{y:35,opacity:.35},{y:0,opacity:1,stagger:.18,duration:1,ease:'power3.out',clearProps:'transform,opacity'}));tweens.push(gsap.fromTo('.orbit-one',{rotate:-18},{rotate:12,duration:2,ease:'power2.out'}))}},{threshold:.25});if(scene)sceneObserver.observe(scene);
 return()=>{observer.disconnect();sceneObserver.disconnect();tweens.forEach(t=>t.kill())};
 });mm.add('(min-width:1101px) and (prefers-reduced-motion: no-preference)',()=>{gsap.to('.orbit-two',{rotate:-25,ease:'none',scrollTrigger:{trigger:'.perspective-scene',start:'top bottom',end:'bottom top',scrub:.4}})});return()=>mm.revert()},[]);return null}
''')
# Remove global smooth scroll: browser position restoration and toolbar changes must be instant.
for f in ['app/globals.css','app/refinement.css']:
 p=r/f;s=p.read_text(encoding='utf-8').replace('scroll-behavior:smooth','scroll-behavior:auto');p.write_text(s,encoding='utf-8')
# Animate consultation state changes, independently of scrolling.
p=r/'components/Consultation.tsx';s=p.read_text(encoding='utf-8').replace('<div className="step-content"','<div key={active} className="step-content"');p.write_text(s,encoding='utf-8')
